def sequential_search(array, element):
    for index, value in enumerate(array):
        if value == element:
            return (True, index)
    return (False, -1)

# Example usage:
assert sequential_search([11, 23, 58, 31, 56, 77, 43, 12, 65, 19], 31) == (True, 3)
