def find_kth(arr1, arr2, k):
    """
    Finds the k-th element in the merged sorted list of two given sorted arrays.

    Args:
    arr1: List[int] - The first sorted array.
    arr2: List[int] - The second sorted array.
    k: int - The position (1-based) of the element to find in the merged sorted array.

    Returns:
    int - The k-th element in the merged sorted array.
    """
    def kth_helper(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        if k == 1:
            return min(a[0], b[0])

        mid_a = k // 2 if len(a) >= k // 2 else len(a)
        mid_b = k // 2 if len(b) >= k // 2 else len(b)

        if a[mid_a - 1] <= b[mid_b - 1]:
            return kth_helper(a[mid_a:], b, k - mid_a)
        else:
            return kth_helper(a, b[mid_b:], k - mid_b)

    return kth_helper(arr1, arr2, k)

# Example test
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
```

