def count_Substrings(s):
    def is_valid_substring(sub):
        return sum(int(ch) for ch in sub) == len(sub)

    n = len(s)
    count = 0

    for i in range(n):
        for j in range(i + 1, n + 1):
            if is_valid_substring(s[i:j]):
                count += 1

    return count

# Example usage:
# assert count_Substrings('112112') == 6
