def recursive_list_sum(lst):
    def flatten_and_sum(sublist):
        total = 0
        for item in sublist:
            if isinstance(item, list):
                total += flatten_and_sum(item)
            else:
                total += item
        return total

    return flatten_and_sum(lst)

# Example usage and test
assert recursive_list_sum([1, 2, [3, 4], [5, 6]]) == 21
```

